const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={hr:'HR',en:'EN',de:'DE',cs:'CS',from:'Od',to:'Do',nightly:'EUR / noć',minNights:'Min. noći',name:'Naziv',alt:'Opis HR',altEn:'Opis EN',altDe:'Opis DE',altCs:'Opis CS',category:'Kategorija',title:'Naslov',description:'Opis',question:'Pitanje',answer:'Odgovor',published:'Objavljen'};
function readable(value,depth=0){if(value==null||value==='')return '—';if(typeof value==='boolean')return value?'Da':'Ne';if(typeof value!=='object')return String(value);if(depth>4)return 'Sadržaj';if(Array.isArray(value))return value.map((v,i)=>`${i+1}. ${readable(v,depth+1)}`).join('\n');return Object.entries(value).filter(([k])=>!['file','url','key','illustrative'].includes(k)).map(([k,v])=>`${names[k]||k}: ${readable(v,depth+1)}`).join('\n')}
export function showPublishReview(changes){
 return new Promise(resolve=>{document.querySelector('#editor-publish-review')?.remove();const dialog=document.createElement('dialog');dialog.id='editor-publish-review';dialog.className='editor-publish-review';dialog.setAttribute('aria-labelledby','publish-review-title');dialog.innerHTML=`<h2 id="publish-review-title">Pregled promjena prije objave</h2><p>Nacrt je spremljen. Javna stranica promijenit će se tek nakon vaše potvrde.</p><p><strong>${changes.length} ${changes.length===1?'promjena':'promjene'} za pregled</strong></p><div class="editor-review-list">${changes.map(row=>`<details><summary><span>${esc(row.section)}</span> ${esc(row.label)}</summary><div class="editor-review-values"><div><h3>Trenutačno objavljeno</h3><pre>${esc(readable(row.before))}</pre></div><div><h3>Nakon objave</h3><pre>${esc(readable(row.after))}</pre></div></div></details>`).join('')}</div><div class="editor-review-actions"><button type="button" class="btn outline" data-review-cancel>Nastavi uređivati</button><button type="button" class="btn" data-review-publish ${changes.length?'':'disabled'}>Potvrdi i objavi ↗</button></div>`;document.body.append(dialog);let done=false;const finish=value=>{if(done)return;done=true;dialog.close();dialog.remove();resolve(value)};dialog.querySelector('[data-review-cancel]').onclick=()=>finish(false);dialog.querySelector('[data-review-publish]').onclick=()=>finish(true);dialog.addEventListener('cancel',event=>{event.preventDefault();finish(false)});dialog.showModal()});
}
